import docx
doc = docx.Document('tests/agent_eval/fixtures/T01_contract_vi.docx')
for child in doc.element.body:
    tag = child.tag.split('}')[-1]
    if tag == 'p':
        p = docx.text.paragraph.Paragraph(child, doc)
        if p.text.strip():
            print(f'P: {p.text[:60]}...')
    elif tag == 'tbl':
        t = docx.table.Table(child, doc)
        print(f'TBL: {len(t.rows)} rows x {len(t.columns)} cols')
